  1	import {
  2	  ApplicationRef,
  3	  Component,
  4	  Injector,
  5	  OnInit,
  6	  effect,
  7	  inject,
  8	  input,
  9	  signal,
 10	  untracked,
 11	} from '@angular/core';
 12	import { FieldTree, FormField, FormRoot, form, validate } from '@angular/forms/signals';
 13	import { Router } from '@angular/router';
 14	import { CLOCK } from '../../core/clock';
 15	import { QuoteStore } from '../../core/quote-store';
 16	import type { FieldConfig, RawValues } from '../../shared/field-config.model';
 17	import { validateField } from '../../shared/field-validators';
 18	import { hydrate } from '../../shared/field-values';
 19	
 20	/**
 21	 * The step 1 form (ADR-0004): Signal Forms over the shared validation core. The editing model is
 22	 * `Record<string, string | boolean>` (never null); each field has exactly one `validate()` that
 23	 * calls the pure `validateField`. Built once per instance, hydrated from the wizard state; a
 24	 * different configuration means a new instance (the page recreates it).
 25	 */
 26	@Component({
 27	  selector: 'app-quote-form',
 28	  imports: [FormField, FormRoot],
 29	  templateUrl: './quote-form.html',
 30	  styleUrl: './quote-form.css',
 31	})
 32	export class QuoteForm implements OnInit {
 33	  readonly configs = input.required<FieldConfig[]>();
 34	  readonly countryCode = input.required<string>();
 35	
 36	  private readonly appRef = inject(ApplicationRef);
 37	  private readonly injector = inject(Injector);
 38	  private readonly clock = inject(CLOCK);
 39	  private readonly quote = inject(QuoteStore);
 40	  private readonly router = inject(Router);
 41	
 42	  protected form!: FieldTree<RawValues>;
 43	  /** Copies the editing model into the wizard state, key by key, only what changed since the last copy. */
 44	  private flushModel: () => void = () => undefined;
 45	
 46	  ngOnInit(): void {
 47	    const configs = this.configs();
 48	    const model = signal<RawValues>(hydrate(configs, this.quote.values()));
 49	    this.form = form(
 50	      model,
 51	      (root) => {
 52	        for (const config of configs) {
 53	          validate(root[config.key], ({ value }) => {
 54	            const message = validateField(config, value(), this.clock());
 55	            return message ? { kind: 'custom', message } : undefined;
 56	          });
 57	        }
 58	      },
 59	      {
 60	        injector: this.injector,
 61	        submission: {
 62	          // Validity is decided on the store values (an unparseable number is '' there), not on
 63	          // the field states: a parse error on an optional field must not block (R2-F01).
 64	          ignoreValidators: 'all',
 65	          action: async (root) => {
 66	            // The model-to-store effect runs on the next change detection; a keyboard Enter can
 67	            // arrive before it (Space on the consent box, then Enter). Flush it so the store
 68	            // holds exactly what the user sees.
 69	            this.flushModel();
 70	            if (this.quote.completeStep1(configs) !== null) {
 71	              await this.router.navigate(['/', this.countryCode().toLowerCase(), 'planes']);
 72	              return undefined;
 73	            }
 74	            const values = this.quote.values();
 75	            const first = configs.find((config) => validateField(config, values[config.key], this.clock()) !== null);
 76	            if (first) root[first.key]().focusBoundControl();
 77	            return undefined;
 78	          },
 79	        },
 80	      },
 81	    );
 82	
 83	    // The raw editing values are written to the wizard state on every change (ADR-0003).
 84	    let synced: RawValues = { ...model() };
 85	    this.flushModel = () => {
 86	      const current = model();
 87	      for (const [key, value] of Object.entries(current)) {
 88	        if (synced[key] !== value) this.quote.setValue(key, value);
 89	      }
 90	      synced = { ...current };
 91	    };
 92	    effect(
 93	      () => {
 94	        model();
 95	        untracked(() => this.flushModel());
 96	      },
 97	      { injector: this.injector },
 98	    );
 99	  }
100	
101	  /** The two narrowing accessors of ADR-0004: the only casts, selected by the field type. */
102	  protected text(key: string): FieldTree<string> {
103	    return this.form[key] as unknown as FieldTree<string>;
104	  }
105	  protected flag(key: string): FieldTree<boolean> {
106	    return this.form[key] as unknown as FieldTree<boolean>;
107	  }
108	
109	  /**
110	   * Runs before the browser applies a keystroke to a number input. Signal Forms writes the model
111	   * back into the DOM from a deferred flush; if that flush is still pending when the next key
112	   * makes the text unparseable (`1` then `e`), it would overwrite the text being typed with the
113	   * stale model value. Flushing now makes it a no-op (the DOM already holds that value), so the
114	   * typed text stays visible. The model is never touched here.
115	   */
116	  protected flushBindings(): void {
117	    this.appRef.tick();
118	  }
119	
120	  /**
121	   * After every input on a number field: text the browser cannot parse (`validity.badInput`) is
122	   * stored as '' (R2-F01), parseable text as typed. The control's own model is left alone on
123	   * purpose: writing '' to it makes Signal Forms write '' into the DOM, which erases the text the
124	   * user typed (R1-F03). Validation, the store, the storage and the output all see ''.
125	   */
126	  protected syncNumber(event: Event, key: string): void {
127	    const el = event.target as HTMLInputElement;
128	    this.quote.setValue(key, el.validity.badInput ? '' : el.value);
129	  }
130	
131	  /**
132	   * The message to show (spec AC-09): unparseable number text is an empty value, so it shows
133	   * `requiredMessage ?? errorMessage` when the field is required and nothing when it is optional.
134	   */
135	  protected errorOf(config: FieldConfig): string | null {
136	    const state = this.form[config.key]();
137	    if (!state.touched()) return null;
138	    const errors = state.errors();
139	    if (errors.some((error) => error.kind === 'parse')) {
140	      return validateField(config, '', this.clock());
141	    }
142	    return state.invalid() ? (errors[0]?.message ?? null) : null;
143	  }
144	
145	  protected describedBy(config: FieldConfig, error: string | null): string | null {
146	    const ids = [
147	      config.helpText ? `${config.key}-help` : '',
148	      error ? `${config.key}-error` : '',
149	    ].filter(Boolean);
150	    return ids.length > 0 ? ids.join(' ') : null;
151	  }
152	}
  1	<form [formRoot]="form" class="form">
  2	  <p class="form__note">Los campos marcados con * son obligatorios.</p>
  3	  @for (config of configs(); track config.key) {
  4	    @let error = errorOf(config);
  5	    @let described = describedBy(config, error);
  6	    @let id = 'field-' + config.key;
  7	    <div class="field" [class.field--checkbox]="config.type === 'checkbox'">
  8	      @if (config.type === 'checkbox') {
  9	        <input
 10	          type="checkbox"
 11	          [id]="id"
 12	          [formField]="flag(config.key)"
 13	          [attr.aria-required]="config.isRequired"
 14	          [attr.aria-invalid]="error ? 'true' : null"
 15	          [attr.aria-describedby]="described"
 16	        />
 17	        <label [for]="id">{{ config.label }}@if (config.isRequired) {<span aria-hidden="true"> *</span>}</label>
 18	      } @else {
 19	        <label [for]="id">{{ config.label }}@if (config.isRequired) {<span aria-hidden="true"> *</span>}</label>
 20	        @switch (config.type) {
 21	          @case ('select') {
 22	            <select
 23	              [id]="id"
 24	              [formField]="text(config.key)"
 25	              [attr.aria-required]="config.isRequired"
 26	              [attr.aria-invalid]="error ? 'true' : null"
 27	              [attr.aria-describedby]="described"
 28	            >
 29	              <option value="" disabled>Selecciona una opción</option>
 30	              @for (option of config.options; track option.value) {
 31	                <option [value]="option.value">{{ option.label }}</option>
 32	              }
 33	            </select>
 34	          }
 35	          @case ('number') {
 36	            <input
 37	              type="number"
 38	              (beforeinput)="flushBindings()"
 39	              (input)="syncNumber($event, config.key)"
 40	              [id]="id"
 41	              [formField]="text(config.key)"
 42	              [attr.placeholder]="config.placeholder ?? null"
 43	              [attr.aria-required]="config.isRequired"
 44	              [attr.aria-invalid]="error ? 'true' : null"
 45	              [attr.aria-describedby]="described"
 46	            />
 47	          }
 48	          @case ('date') {
 49	            <input
 50	              type="date"
 51	              [id]="id"
 52	              [formField]="text(config.key)"
 53	              [attr.aria-required]="config.isRequired"
 54	              [attr.aria-invalid]="error ? 'true' : null"
 55	              [attr.aria-describedby]="described"
 56	            />
 57	          }
 58	          @default {
 59	            <input
 60	              type="text"
 61	              [id]="id"
 62	              [formField]="text(config.key)"
 63	              [attr.placeholder]="config.placeholder ?? null"
 64	              [attr.aria-required]="config.isRequired"
 65	              [attr.aria-invalid]="error ? 'true' : null"
 66	              [attr.aria-describedby]="described"
 67	            />
 68	          }
 69	        }
 70	      }
 71	      @if (config.helpText) {
 72	        <p class="field__help" [id]="config.key + '-help'">{{ config.helpText }}</p>
 73	      }
 74	      @if (error) {
 75	        <p class="field__error" [id]="config.key + '-error'" role="alert">{{ error }}</p>
 76	      }
 77	    </div>
 78	  }
 79	  <button type="submit" class="form__submit">Continuar</button>
 80	</form>

